class Event:
    def __init__(self, timestamp, is_start):
        self.timestamp = timestamp
        self.is_start = is_start

def required_capacity(bookings: list[list[int]]) -> int:
    # Define a helper function to create events
    def create_events(bookings):
        events = []
        for start, end in bookings:
            events.append(Event(start, True))
            events.append(Event(end, False))
        return events

    # Create events and sort them
    events = create_events(bookings)
    events.sort(key=lambda x: (x.timestamp, x.is_start))

    active_bookings = 0
    max_active_bookings = 0

    for event in events:
        if event.is_start:
            active_bookings += 1
            max_active_bookings = max(max_active_bookings, active_bookings)
        else:
            active_bookings -= 1

    return max_active_bookings
